SET NAMES utf8mb4;

-- ============================================================
-- PART 1: 语文[职高] — 6个应用文写作 L4 节点填充
-- ============================================================
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=20 AND name='应用文写作(书信/通知)' AND level=3 LIMIT 1);

UPDATE knowledge_nodes SET content =
'【一句话定义】\n通知是机关、团体、企事业单位或个人向特定对象告知事项时使用的一种应用文体，常见有书面通知和口头通知两种形式。\n\n【具体说明】\n① 书面通知格式：标题(NOTICE居中) → 正文(时间·地点·事项·要求，直入主题) → 落款(发文单位+日期)。正文第一句常用"Attention, please!"或直接陈述。② 口头通知格式：开场语(May I have your attention, please? / Attention, everyone!) → 正文 → 结束语(That''s all. Thank you.)。③ 核心要素：必须包含What(什么事)/When(何时)/Where(何地)/Who(谁参加)四要素。④ 语言特点：简洁明了，用祈使句(Please come on time.)，避免情感色彩。\n\n【常见错误】\n1. 遗漏通知要素→What/When/Where必有，否则信息不完整\n2. 文体混淆→书面通知用标题NOTICE和落款，口头通知有开场呼语\n3. 时间地点写成模糊表达→"明天下午"应为具体时间"tomorrow at 2:00 p.m."\n\n【考试方向】\n应用文写作题：根据提示写一份约80词的英文通知。'
WHERE parent_id=@l3 AND name='通知' AND content IS NULL;

UPDATE knowledge_nodes SET content =
'【一句话定义】\n启事是单位或个人向公众公开说明某事或请求协助时使用的一种应用文书，常见有寻物启事、招领启事、招聘启事等。\n\n【具体说明】\n① 格式：标题(启事类型居中，如Lost/Found/Wanted) → 正文(说明事由·物品特征·联系方式) → 落款(发布人+日期)。② 寻物启事要点：描述丢失物品的特征(颜色·大小·品牌)、丢失时间和地点、酬谢方式、联系方式。正文首句常用"I lost a..."或"A...was lost..."。③ 招领启事要点：描述捡到物品的大致特征(不必太详细以防冒领)、认领方式。④ 招聘启事要点：招聘条件(age/education/experience)、工作内容(Job duties)、待遇(salary)、联系方式。\n\n【常见错误】\n1. 格式漏项→标题(Lost/Found)必须标明启事类型\n2. 寻物与招领不分→寻物详细描述，招领适度模糊\n3. 联系方式缺失→寻物必须有联系方式(phone number/email)\n\n【考试方向】\n应用文写作题：根据情境写一份寻物启事或招领启事。'
WHERE parent_id=@l3 AND name='启事' AND content IS NULL;

UPDATE knowledge_nodes SET content =
'【一句话定义】\n书信是个人或单位之间传递信息、表达情感、处理事务时使用的应用文体，格式包含信头/称呼/正文/结束语/署名/日期六大要素。\n\n【具体说明】\n① 格式六要素：1.信头(右上角写日期→March 15, 2026) 2.称呼(Dear...,加逗号) 3.正文(分段写·开头句+主体+结尾句) 4.结束语(Yours sincerely,/Yours faithfully,等) 5.署名 6.日期。② 开头常用句：I''m writing to tell you/invite you...; How are you doing?; Thank you for your letter. ③ 结尾常用句：Looking forward to your reply.; I hope to hear from you soon.; Best wishes to you! ④ 称呼与结束语匹配：Dear Sir/Madam→Yours faithfully；Dear+人名→Yours sincerely/Yours。⑤ 正文要求：语言得体、感情真挚、条理清楚、无语法错误。\n\n【常见错误】\n1. 日期位置错误→日期应在右上角信头位置，非署名下方\n2. 结束语漏写→书信必须写结束语(Yours sincerely等)\n3. Looking forward to后忘加V-ing→应为hearing，非hear\n\n【考试方向】\n应用文写作题：根据提示写一封约80词的英文书信（感谢信/邀请信/建议信等）。'
WHERE parent_id=@l3 AND name='书信' AND content IS NULL;

UPDATE knowledge_nodes SET content =
'【一句话定义】\n条据是日常生活和工作中用作凭证或说明的简便应用文，包括凭证条据（借条/收条/领条/欠条）和说明条据（请假条/留言条/托事条）两类。\n\n【具体说明】\n① 凭证条据格式：标题(IOU/Receipt居中) → 正文("今借到/今收到..."+物品/金额+数量大写) → 落款(经手人签名+日期)。金额数字必须同时用阿拉伯数字和中文大写。② 说明条据格式：称呼→正文(事由+请求)→落款(署名+日期)。请假条常用句式：Please excuse...from...for...; I am writing to ask for...leave。③ 语言特点：简洁中立，不打感情牌，客观陈述事实。④ 借条特别注意：写明归还日期和物品完好度确认。\n\n【常见错误】\n1. 金额只有一种写法→必须阿拉伯数字+中文大写双重保障\n2. 借条和收条混淆→借条承诺归还，收条确认收到\n3. 请假条缺请假时间→From [start] to [end] 必须明确\n\n【考试方向】\n应用文写作题：根据情境写一张借条、收条或请假条。'
WHERE parent_id=@l3 AND name='条据' AND content IS NULL;

UPDATE knowledge_nodes SET content =
'【一句话定义】\n总结是对过去一定时期内的工作、学习或活动进行全面回顾、分析评价和提炼经验教训的应用文体，常见有工作总结、学习总结和活动总结。\n\n【具体说明】\n① 格式：标题→前言(概述背景和总体评价)→正文(成绩·不足·原因·措施，分段叙述)→结尾(提出改进方向或展望)。② 写作思路：先写出做了哪些工作或学习→其次写出哪些做得好、哪些不好→再次分析成功/失败原因→最后提出改进措施。③ 语言特点：客观平实，用数据和事实说话，忌空洞口号。如"本学期我完成了5篇英语阅读理解练习"vs"我收获很大"。④ 关键技巧：具体化(不是"我进步了"而是"阅读理解正确率从60%提高到80%")，结构化(分点叙述)，客观化(既写成绩也写不足)。\n\n【常见错误】\n1. 只有成绩无不足→总结应客观全面，只写成绩是自我表扬\n2. 只有现象无原因→"我做题慢了"应补充"因为没有记公式，每次都要翻书"\n3. 只有总结无提高→结尾应提出改进方向和具体措施\n\n【考试方向】\n应用文写作题：根据材料或情境写一份学习总结或活动总结。'
WHERE parent_id=@l3 AND name='总结' AND content IS NULL;

UPDATE knowledge_nodes SET content =
'【一句话定义】\n会议记录是在会议过程中由专门记录人员把会议的组织情况和具体内容如实地记载下来而形成的书面材料，是会议的原始凭证和后续执行的依据。\n\n【具体说明】\n① 格式组成：会议名称→时间·地点→出席人·缺席人→主持人·记录人→议题→讨论内容(逐人发言)→决议(表决结果+执行责任人+完成时限)。② 记录技巧：发言人姓名+核心观点简要记录(不需逐字逐句)；"一致同意"直接写决议，有分歧则注明"×人同意，×人反对，×人弃权"。③ 语言特点：客观真实，不添加个人评论，直接引用发言人关键句时用引号标明。④ 注意事项：会议结束后需主持人签字确认，重要的会议记录需存档备查。\n\n【常见错误】\n1. 遗漏组织信息→时间/地点/出席人/主持人缺一不可\n2. 记录加个人评价→"他的观点荒谬"之类主观表达不应出现\n3. 决议不含执行人→"下次改进"太模糊，应写明"张老师于5月1日前完成教案修订"\n\n【考试方向】\n应用文写作题：根据提供的会议情景素材，整理一份规范的会议记录。'
WHERE parent_id=@l3 AND name='会议记录' AND content IS NULL;

SELECT 'Part1: Chinese L4 done' AS result;


-- ============================================================
-- PART 2: 数学[职高] — 22个空L4节点填充
-- ============================================================

-- 数列 (7个)
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='数列的概念' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n数列是按一定次序排列的一列数，每个数都是数列的一项，通项公式a_n=f(n)是描述第n项与项数n关系的表达式，是数列的核心工具。\n\n【具体说明】\n① 数列的表示方法有三种：列举法{1,3,5,7,…}、通项公式法a_n=2n−1、递推公式法a_1=1,a_{n+1}=a_n+2。② 数列分类：按项数分→有穷数列(项数有限)、无穷数列(项数无限)；按单调性分→递增数列(a_{n+1}>a_n)、递减数列、常值数列、摆动数列。③ 通项公式的找法：观察方法→先看差是否常值(等差)，再看比是否常值(等比)，都不是则尝试n的二次式。④ 注意n是正整数，验证通项时应代入n=1,2,3检验。\n\n【常见错误】\n1. 混淆项与项数→a_n的第n项就是n=1时a_1，不是"第1项是a_0"\n2. 数列与集合混淆→数列有顺序且可重复，集合无序不重复\n\n【考试方向】\n单项选择题：根据数列前几项找出通项公式。' WHERE id=3132;

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='等差数列' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n等差数列从第二项起每一项与它的前一项的差等于同一个常数d（公差），通项公式为a_n=a_1+(n−1)d。\n\n【具体说明】\n① 公差d计算：d=a_n−a_{n−1}（任意相邻两项差恒定）；已知任意两项求公差公式d=(a_n−a_m)/(n−m)（n≠m）。② 等差中项：a,b,c三数成等差⇔2b=a+c（b是a与c的等差中项）。③ 证明一个数列是等差数列的方法：证a_{n+1}−a_n=常数d（定义法），或2a_{n+1}=a_n+a_{n+2}（中项法）。④ 通项公式a_n关于n是一次函数形式：当d≠0时图像是分布在直线上的离散点，d的正负决定递增/递减。\n\n【常见错误】\n1. 公差公式分母写反→d=(a_n−a_m)/(n−m)中分母是项数差n−m，不是m−n\n2. 证明等差数列时只验证了前3项→必须证明对任意n成立\n\n【考试方向】\n单选/填空：求公差、通项；证明某个数列是等差数列。' WHERE id=3133;

UPDATE knowledge_nodes SET content = '【一句话定义】\n等差数列前n项和公式有S_n=n(a_1+a_n)/2和S_n=na_1+n(n−1)d/2两种形式，推导方法为"倒序相加法"。\n\n【具体说明】\n① 倒序相加法推导：S_n=a_1+a_2+…+a_n，同时S_n=a_n+a_{n−1}+…+a_1，相加得2S_n=n(a_1+a_n)。② 选择策略：已知首项和末项用第一式；已知首项和公差用第二式；两者相通可互化。③ 当d≠0时，S_n是关于n的二次函数且常数项为零，利用这个特征可以计算特定项的累积。④ 求最值问题：a_1>0且d<0时S_n有最大值（先增后减）；a_1<0且d>0时S_n有最小值。\n\n【常见错误】\n1. 两个公式混用导致项数n误算→应先确认已知量再用对应公式\n2. 做差比较不等式时忘记n是正整数→S_n最大值点应是a_n≥0的最后一项\n\n【考试方向】\n填空/解答：求和、求项数、求公差、求最值应用题。' WHERE id=3134;

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='等比数列' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n等比数列从第二项起每一项与它的前一项的比等于同一个非零常数q（公比），通项公式为a_n=a_1·q^{n−1}（q≠0且各项均不为0）。\n\n【具体说明】\n① 公比q计算：q=a_n/a_{n−1}（任意相邻两项比恒定）；已知任意两项求公比由a_n=a_m·q^{n−m}得q^{n−m}=a_n/a_m。② 等比中项：a,G,b三数成等比⇔G²=ab（G=±√(ab)，符号由数列各项正负决定）。③ 判断一个数列是等比→证a_{n+1}/a_n=常数q且各项不为0。④ 等比数列的增长速度：|q|>1时急剧增长，0<|q|<1时逐渐趋近于0，q=1时各项相同。\n\n【常见错误】\n1. 忽略q≠0且各项≠0→有0则不是等比（等比数列定义要求各项不为0）\n2. 等比中项取正不取负→√(ab)可能是负值，取决于a和b的正负\n\n【考试方向】\n单选/填空：求公比、通项；判断等比关系。' WHERE id=3135;

UPDATE knowledge_nodes SET content = '【一句话定义】\n等比数列前n项和当q=1时S_n=na_1；当q≠1时S_n=a_1(1−q^n)/(1−q)=a_1(q^n−1)/(q−1)，推导方法为"错位相减法"。\n\n【具体说明】\n① 错位相减法推导：S_n=a_1+a_1q+…+a_1q^{n−1}①，乘q得qS_n=a_1q+a_1q^2+…+a_1q^n②，①−②消去中间项（错位相减），整理得S_n公式。② 使用前务必先判断q是否为1！q=1时各加数相同。③ 公式记忆技巧：分子为a_1×(1−q^n)，分母为1−q，也可分子为a_1×(q^n−1)分母为q−1，两式等价。④ 等比增长应用：复利计算(本金×(1+利率)^n)，增长率模型。\n\n【常见错误】\n1. 忘记讨论q=1的特例→直接用公式分母为0，是最常见的扣分点\n2. q^n计算时指数n不是项数→如对a_3+a_4+a_5求和，代入公式时项数是3\n\n【考试方向】\n填空/解答：求前n项和，等比综合应用题（复利/增长率）。' WHERE id=3136;

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='数列求和' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n分组求和法是将通项拆分为几个可分别求和的部分（如等差+等比），对各部分分别求和后再合并结果。\n\n【具体说明】\n① 适用类型：通项a_n是等差数列通项±等比数列通项，如a_n=2n+3^n。② 操作步骤：写出通项→拆分(a_n=等差项±等比项)→对等差项用等差数列求和公式→对等比项用等比数列求和公式→合并得到S_n。③ 注意项数一致性：拆分后两部分项数相同（都是前n项）。④ 对于等差×等比的形式(a_n=n·2^n)，不能用分组求和，应用错位相减法。\n\n【常见错误】\n1. 误将等差×等比当成分组求和→遇到乘积形式用错位相减法\n2. 各部分项数不一致→拆分后每部分求和都从第1项到第n项\n\n【考试方向】\n填空/解答：分组求和求S_n。' WHERE id=3137;

UPDATE knowledge_nodes SET content = '【一句话定义】\n裂项相消法是将一个分式拆分为两个简单分式的差，使求和时前后项抵消仅留下首尾少数项，从而快速求出和。\n\n【具体说明】\n① 核心公式：1/[n(n+1)]=1/n−1/(n+1)；1/[n(n+k)]=(1/k)(1/n−1/(n+k))；1/[(2n−1)(2n+1)]=(1/2)[1/(2n−1)−1/(2n+1)]。② 操作步骤：写出通项→裂项拆分→写出前3项和最后2项→观察抵消规律→写出S_n=首项+末项（中间项全部抵消）。③ 重点是要确认哪些项抵消了哪些没抵消：前段留下的前k项和后段留的后k项（k是分母差的绝对值）。④ 不是所有分式都可裂项——分母必须能分解为可相消的因式乘积。\n\n【常见错误】\n1. 只写出前2项就写求和结果→必须写出末项确认抵消完整\n2. 漏乘系数1/k→分母差为k时须乘1/k\n\n【考试方向】\n填空：用裂项相消法求分式型数列的和。' WHERE id=3138;


-- 平面向量 (5个)
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='向量的概念与线性运算' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n向量是既有大小又有方向的量，三要素为大小（模）、方向和作用点；自由向量可平移，两个向量模相等且方向相同即相等。\n\n【具体说明】\n① 向量表示：几何表示用有向线段AB→（A为起点B为终点），印刷体用黑体a，手写用a上加箭头。② 零向量0̄：模长为0，方向任意。单位向量：模长为1的向量（不唯一）。③ 共线向量（平行向量）：方向相同或相反的向量，可平移到同一条直线上。两个非零向量平行→ā=k·b̄（存在实数k）→对应坐标成比例。④ 向量相等：大小相等+方向相同；起点可以不同（自由向量可平移）。\n\n【常见错误】\n1. 混淆向量与有向线段→向量可平移，有向线段固定起点\n2. 零向量方向"任意"→零向量不是无方向，是任何方向\n\n【考试方向】\n单选/判断：向量基本概念辨析；平行向量的判定。' WHERE id=3142;

UPDATE knowledge_nodes SET content = '【一句话定义】\n向量加减法遵循三角形法则（首尾相接）和平行四边形法则（共同起点）；向量数乘λā结果模为|λ||ā|，λ>0同向λ<0反向。\n\n【具体说明】\n① 三角形法则：ā+b̄的作法→从ā的起点出发到b̄的终点的向量。要点：ā的终点与b̄的起点相接。② 平行四边形法则：ā+b̄是以ā,b̄为邻边的平行四边形的对角线。③ 减法：ā−b̄=ā+(−b̄)，即从b̄终点指向ā终点的向量(口诀"终点指向终点")。④ 数乘运算律：λ(ā+b̄)=λā+λb̄；(λ+μ)ā=λā+μā；λ(μā)=(λμ)ā。⑤ 几何意义：λā是将ā沿相同(或相反)方向按比例缩放|λ|倍。\n\n【常见错误】\n1. 减法方向反了→ā−b̄的向量指向是从b̄终点到ā终点，不是反过来\n2. 数乘忘记改变模长→|λā|=|λ|·|ā|，即缩放比例后模长也要变\n\n【考试方向】\n单选/填空：向量线性运算的结果坐标或模长。' WHERE id=3143;

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='向量的数量积' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n数量积ā·b̄=|ā||b̄|cosθ（θ为ā与b̄的夹角），结果是数量（不是向量），坐标公式ā·b̄=x₁x₂+y₁y₂。\n\n【具体说明】\n① 数量积的几何意义：|ā|·(|b̄|cosθ)即一个向量的模乘以另一个向量在该方向上的投影。② 特有性质：ā⊥b̄⇔ā·b̄=0（最重要的垂直判定！）；ā平行于b̄⇔ā·b̄=±|ā||b̄|；³|ā|²=ā·ā。③ 运算律：交换律ā·b̄=b̄·ā对数量积成立；分配律成立；结合律(λā)·b̄=λ(ā·b̄)；注意ā·(b̄·c̄)无意义（数量积只能二向量运算）。④ 夹角公式：cosθ=(ā·b̄)/(|ā||b̄|)=(x₁x₂+y₁y₂)/[√(x₁²+y₁²)·√(x₂²+y₂²)]。\n\n【常见错误】\n1. 数量积结果写成向量→ā·b̄是数量不是向量\n2. 忘记开根号求模长→|ā|=√(x²+y²)，不是x²+y²\n\n【考试方向】\n单选/填空：计算数量积，求两向量夹角，证明垂直。' WHERE id=3144;

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='向量的坐标运算' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n向量坐标形式ā=(x,y)表示从原点指向点(x,y)的位置向量。已知点A(x₁,y₁)和B(x₂,y₂)，则AB→=(x₂−x₁,y₂−y₁)，即终点坐标减起点坐标。\n\n【具体说明】\n① 坐标系中向量运算全部化为坐标运算：ā±b̄=(x₁±x₂,y₁±y₂)；λā=(λx₁,λy₁)。② AB→的模长即为AB两点间距离公式：|AB|=√((x₂−x₁)²+(y₂−y₁)²)。③ 中点坐标公式：AB中点M坐标为((x₁+x₂)/2,(y₁+y₂)/2); 对应向量OM→=(ā+b̄)/2。④ 定比分点(外分点)公式：若AP→=λPB→，则P坐标为((x₁+λx₂)/(1+λ),(y₁+λy₂)/(1+λ))。\n\n【常见错误】\n1. AB→写成起点减终点→正确是"终点减起点"=B−A\n2. 模长公式忘记开根号→|ā|=√(x²+y²)，这是最易错的\n\n【考试方向】\n单选/填空：已知两点坐标求向量坐标；计算向量模长。' WHERE id=3145;

UPDATE knowledge_nodes SET content = '【一句话定义】\n坐标运算在向量平行、垂直和夹角问题中的应用是核心考点。平行(共线)用叉积为零判定，垂直用点积为零判定。\n\n【具体说明】\n① 共线判定（平行）：ā∥b̄⇔x₁y₂−x₂y₁=0（叉积为零，即对应坐标成比例）。注意零向量与任意向量都平行。② 垂直判定：ā⊥b̄⇔x₁x₂+y₁y₂=0（点积为零）。这是垂直的最直接判定方法。③ 夹角计算：将数量积公式cosθ=(x₁x₂+y₁y₂)/[√(x₁²+y₁²)·√(x₂²+y₂²)]代入计算，θ∈[0,π]。④ 判断三点是否共线：计算AB→和AC→，若AB→平行AC→则三点共线。\n\n【常见错误】\n1. 平行与垂直的坐标条件记反→平行看叉积（对角相减），垂直看点积（相同相乘再加）\n2. 夹角公式运算繁琐出错→先约分再开根号\n\n【考试方向】\n单选/填空：判断向量平行/垂直；求夹角；判定三点共线。' WHERE id=3146;


-- 立体几何 (4个)
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='空间几何体' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n常见几何体的表面积计算是立体几何的基础应用，每种几何体有其独特的表面积公式，需区分侧面积和全面积（侧面积+底面积）。\n\n【具体说明】\n① 多面体：正方体表面积S=6a²；长方体S=2(ab+ac+bc)（其中a,b,c是长宽高）；三棱柱S=2S_底+S_侧（S_侧=底面周长×高）。② 圆柱：侧面积S_侧=2πrh，全面积S=2πr²+2πrh=2πr(r+h)。③ 圆锥：侧面积S_侧=πrl（l为母线长l=√(r²+h²)），全面积S=πr²+πrl=πr(r+l)。④ 球：表面积S=4πR²（R是半径），球体积的推导关键数4π是4个π。⑤ 解题步骤：区分已知量→代入对应公式→注意单位换算（1m²=10⁴cm²）。\n\n【常见错误】\n1. 圆锥表面积漏加πr²→全面积=πr²+πrl，只写侧面积扣分\n2. 球的表面积4πR²与体积⁴⁄₃πR³混淆→S有"面"(表面积)与R²，V有"积"与R³\n\n【考试方向】\n单选/填空：代入数据计算几何体的表面积。' WHERE id=3149;

UPDATE knowledge_nodes SET content = '【一句话定义】\n几何体体积计算遵循柱体V=S_底·h、锥体V=⅓S_底·h、球体V=⁴⁄₃πR³的基本公式体系。\n\n【具体说明】\n① 柱体体积V=S_底×h（通用公式——底面是任意的，统一乘以高）。圆柱V=πr²h是特例。② 锥体体积V=⅓S_底×h（与等底等高柱体体积比为1:3）。圆锥V=⅓πr²h。**注意系数⅓是最容易漏的！**③ 球体体积V=⁴⁄₃πR³。与表面积S=4πR²搭配记忆：对R求导S′=8πR=球体积的增长率。④ 体积单位换算：1m³=10⁶cm³，1L=1dm³=1000cm³。⑤ 组合体体积：先拆分成基本几何体→分别求体积→相加（组合体）或相减（挖掉部分）。\n\n【常见错误】\n1. 锥体漏乘⅓→V=⅓πr²h不是πr²h\n2. 球的体积用错公式→V=(4/3)πR³，不是(3/4)πR³\n\n【考试方向】\n单选/填空：计算几何体的体积；组合体体积计算。' WHERE id=3150;

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='点线面的位置关系' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n线面平行指平面外一条直线与平面内某条直线平行，则这条直线与平面平行。线面垂直指一条直线与平面内两条相交直线都垂直，则这条直线与平面垂直。\n\n【具体说明】\n① 线面平行判定定理（最重要的定理之一）：a⊄α, b⊂α, a∥b⇒a∥α。注意条件必须满足"直线在平面外"和"与平面内一条直线平行"。② 线面垂直判定定理：l⊥a, l⊥b, a∩b=P, a⊂α, b⊂α⇒l⊥α。关键：必须垂直于平面内"两条相交直线"（一条不够!）。③ 性质定理：若a∥α，过a的平面与α相交于b，则a∥b。④ 三垂线定理及逆定理：斜线在平面内的射影与平面内一直线垂直⇔斜线与该直线垂直。\n\n【常见错误】\n1. 线面垂直用一条直线判定→必须"两条相交直线"才成立\n2. 线面平行忘记"直线在平面外"条件→在平面内则不是平行问题\n\n【考试方向】\n单选/判断：判定线面平行/垂直关系；性质定理应用。' WHERE id=3151;

UPDATE knowledge_nodes SET content = '【一句话定义】\n面面平行的判定：一个平面内的两条相交直线分别平行于另一个平面，则两平面平行。面面垂直的判定：一个平面包含另一个平面的垂线，则两平面垂直。\n\n【具体说明】\n① 面面平行判定定理：a⊂α, b⊂α, a∩b=P, a∥β, b∥β⇒α∥β。核心是两个"相交"直线。② 面面平行性质：两平行平面与第三个平面相交，交线平行；夹在两平行平面间的平行线段相等。③ 面面垂直判定定理：l⊥β且l⊂α⇒α⊥β（一平面包含另一平面的垂线）。④ 面面垂直性质：两平面垂直，则一平面内垂直于交线的直线必垂直于另一平面。⑤ 二面角：从棱出发两个半平面组成的图形，二面角的平面角的求法是考查重点。\n\n【常见错误】\n1. 面面平行只用两条平行线判定→必须是"相交"的两条直线\n2. 面面垂直判定时漏掉"l在α内"的条件\n\n【考试方向】\n单选/判断：判定面面平行/垂直关系；求二面角。' WHERE id=3152;


-- 平面解析几何——直线与圆 (6个)
SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='直线方程' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n直线的倾斜角α∈[0°,180°)是直线向上的方向与x轴正方向所成的最小正角，斜率k=tanα(α≠90°)，过两点P₁(x₁,y₁),P₂(x₂,y₂)的斜率k=(y₂−y₁)/(x₂−x₁)（x₁≠x₂）。\n\n【具体说明】\n① 倾斜角的范围是[0°,180°)，α=0°时直线水平，α=90°时直线垂直（无斜率）。② 斜率与方向的关系：k>0→直线上升(锐角)；k<0→直线下降(钝角)；k=0→水平(α=0°)；k不存在→垂直(α=90°)。③ 斜率的两点坐标公式：k=(y₂−y₁)/(x₂−x₁)，分母为零时斜率不存在。当x₁=x₂时直线垂直x轴，方程为x=x₁。④ 垂直直线的斜率关系：若两直线均不水平也不垂直，则L₁⊥L₂⇔k₁·k₂=−1。两直线平行⇔k₁=k₂。\n\n【常见错误】\n1. 倾斜角与斜率混淆→倾斜角是角度，斜率是数值(tan)，两者通过tanα=k关联\n2. 垂直判定k₁k₂=−1的前提是两直线都有斜率→水平与垂直直线须单独讨论\n\n【考试方向】\n单选/填空：求直线斜率和倾斜角；判断两直线的位置关系。' WHERE id=3156;

UPDATE knowledge_nodes SET content = '【一句话定义】\n直线的五种方程形式：点斜式y−y₀=k(x−x₀)、斜截式y=kx+b、两点式(y−y₁)/(y₂−y₁)=(x−x₁)/(x₂−x₁)、截距式x/a+y/b=1(a,b≠0)、一般式Ax+By+C=0，每种形式有其适用场景和优点。\n\n【具体说明】\n① 点斜式(最常用)：已知斜率k和一点(x₀,y₀)即可写出方程。优点是可以立刻写，缺点是垂直x轴时斜率不存在不能用。② 斜截式：可直观读出斜率和y轴截距(0,b)。k为斜率，b为y截距。③ 截距式：直接读出在x轴和y轴上的截距a和b，用在已知两截距时最方便（a,b均不能为0）。④ 一般式：Ax+By+C=0（A,B不同时为0），斜率k=−A/B(B≠0)，截距形式统一，适合进行代数运算。\n\n【常见错误】\n1. 点斜式括号内符号→过点(2,−3)斜率4的方程是y+3=4(x−2)，注意是"−(−3)"=+3\n2. 截距式的a和b不写倒数→x/2+y/3=1不是2x+3y=1\n\n【考试方向】\n单选/填空：根据条件写出直线方程；方程形式互化。' WHERE id=3157;

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='圆的方程' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n圆的标准方程为(x−a)²+(y−b)²=r²，圆心坐标(a,b)，半径为r。此形式可直接读出圆心和半径。\n\n【具体说明】\n① 标准方程的三个几何要素：圆心横坐标a、圆心纵坐标b、半径r。方程展开后就是一般方程x²+y²+Dx+Ey+F=0。② 解题关键：已知圆心和半径直接用标准方程。圆心在原点时退化为x²+y²=r²。③ 求圆方程三步法：确定圆心坐标(找对称中心或给定条件)→确定半径(距离公式或给定条件)→代入标准方程。④ 点与圆的位置关系：点P到圆心O的距离d，比较d与r——d<r点在圆内，d=r在圆上，d>r在圆外。\n\n【常见错误】\n1. 标准方程括号内符号→圆心(2,−3)的方程是(x−2)²+(y+3)²=r²，不是(x−2)²+(y−3)²\n2. 半径忘记平方→方程右端是r²不是r\n\n【考试方向】\n单选/填空：写出圆的标准方程；求圆心和半径。' WHERE id=3158;

UPDATE knowledge_nodes SET content = '【一句话定义】\n圆的一般方程为x²+y²+Dx+Ey+F=0，当D²+E²−4F>0时表示圆，圆心坐标为(−D/2,−E/2)，半径r=√(D²+E²−4F)/2。\n\n【具体说明】\n① 判别条件：D²+E²−4F>0→圆；D²+E²−4F=0→一个点（点圆）；D²+E²−4F<0→无轨迹（虚圆）。② 配方化标准式的方法：x²+Dx=(x+D/2)²−D²/4，同样处理y项。将一般式配方后与标准式对比。③ 与标准方程互化：标准→一般（展开+移项），一般→标准（配方+移项），两者等价。④ 求半径注意除以2：r=√(D²+E²−4F)/2（分母上的2不能忘！）。\n\n【常见错误】\n1. 半径除以2忘记→r=√(D²+E²−4F)/2，只写根号里的2丢掉了\n2. 圆心坐标负号→(−D/2,−E/2)，是D和E的"−一半"\n\n【考试方向】\n单选/填空：从一般式配方化标准式。' WHERE id=3159;

SET @l3 = (SELECT id FROM knowledge_nodes WHERE subject_id=22 AND name='直线与圆的位置关系' AND level=3 LIMIT 1);
UPDATE knowledge_nodes SET content = '【一句话定义】\n直线与圆的位置关系由圆心到直线的距离d与半径r比较判定：d<r⇔直线与圆相交（两个交点）；d=r⇔相切（一个交点）；d>r⇔相离（无交点）。\n\n【具体说明】\n① 距离公式：点(a,b)到直线Ax+By+C=0的距离d=|Aa+Bb+C|/√(A²+B²)。将圆心(a,b)代入。② 代数法判定：联立直线方程和圆方程→整理成关于x的一元二次方程→计算判别式Δ=b²−4ac→Δ>0相交/Δ=0相切/Δ<0相离。③ 几何法(推荐)：用距离公式算d→与r比较。通常几何法比代数法更快。④ 切线问题：过圆上一点(x₀,y₀)的切线方程(x₀−a)(x−a)+(y₀−b)(y−b)=r²。\n\n【常见错误】\n1. 距离公式分子忘加绝对值→距离必须非负！\n2. 判别式法与几何法混淆→两种方法等价，选最快方案\n\n【考试方向】\n单选/解答：判断直线与圆位置关系；求参数范围。' WHERE id=3160;

UPDATE knowledge_nodes SET content = '【一句话定义】\n弦长公式l=2√(r²−d²)(其中d是圆心到直线的距离)用于计算圆被直线截得的弦的长度。切线问题需区分圆上一点和圆外一点。\n\n【具体说明】\n① 弦长公式推导：设圆心到直线的距离为d，弦心距为d→用勾股定理：半弦长l/2=√(r²−d²)→全弦长l=2√(r²−d²)。② 步骤：先将直线写成一般式→算出圆心到直线的距离d→代入弦长公式。③ 过圆上一点的切线：切线与圆心到该点的连线垂直。若点在圆上且圆心为(a,b)，切线方程为(x₀−a)(x−a)+(y₀−b)(y−b)=r²。④ 过圆外一点的切线：设切线斜率k→用点斜式写出切线方程→圆心到该直线距离等于半径→解出k。通常有两条切线（斜率不存在的特殊情况要单独讨论）。\n\n【常见错误】\n1. 弦长公式忘记乘2→l=2√(r²−d²)中的2是最常见的丢分\n2. 圆外一点切线漏讨论斜率不存在的情况→设斜率k前须检查k不存在的情况\n\n【考试方向】\n填空/解答：求弦长；求切线方程。' WHERE id=3161;

SELECT 'Part2: Math L4 done' AS result;
